changeSet.sql:
ALTER TABLE node_sources DROP CONSTRAINT node_sources_pkey;

ALTER TABLE node_sources ADD COLUMN id UUID DEFAULT uuid_generate_v4();
UPDATE node_sources SET id = uuid_generate_v4() WHERE id IS NULL;
ALTER TABLE node_sources ALTER COLUMN id SET NOT NULL;
ALTER TABLE node_sources ADD PRIMARY KEY (id);

CREATE INDEX idx_node_sources_node_id ON node_sources(node_id);

rollback.sql:
DROP INDEX IF EXISTS idx_node_sources_node_id;
ALTER TABLE node_sources DROP CONSTRAINT node_sources_pkey;
ALTER TABLE node_sources DROP COLUMN id;
ALTER TABLE node_sources ADD PRIMARY KEY (node_id, source_id);
